var _markdown = "\n\n`CEntity.h` · 继承 `CPlaceable`\n\nPed / Vehicle / Object 共同基类。删实体走正确 Destroy 路径，别乱 `delete`。\n\n## 取模型与类型 [#取模型与类型]\n\n<Api name=\"m_nModelIndex / m_nType / m_nStatus\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      short m_nModelIndex;\n      eEntityType m_nType : 3;\n      eEntityStatus m_nStatus : 5;\n      unsigned char m_nAreaCode;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (entity && entity->m_nModelIndex == modelId) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 可见与碰撞标志 [#可见与碰撞标志]\n\n<Api name=\"bIsVisible / bUsesCollision / bIsStatic\">\n  bitfield，直接改要小心。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool bIsVisible : 1;\n      bool bUsesCollision : 1;\n      bool bIsStatic : 1;\n      bool bDontStream : 1;\n      // 其余见 CEntity.h\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      entity->bIsVisible = true;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 坐标与传送 [#坐标与传送]\n\n<Api name=\"GetPosition / Teleport\">\n  逻辑帧调用。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CVector GetPosition();\n      void Teleport(CVector destination, bool resetRotation = false);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CVector p = entity->GetPosition();\n      entity->Teleport(CVector(x, y, z), false);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 换模型 [#换模型]\n\n<Api name=\"SetModelIndex / CreateRwObject\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void SetModelIndex(unsigned int index);\n      void SetModelIndexNoCreate(unsigned int index);\n      void CreateRwObject();\n      void DeleteRwObject();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 模型先 Streaming 加载再 SetModelIndex\n      entity->SetModelIndex(modelId);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 进出世界 [#进出世界]\n\n<Api name=\"Add / Remove\">\n  与 `CWorld::Add` / `Remove` 相关，脚本实体生命周期要对。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void Add();\n      void Remove();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 优先用游戏提供的创建/销毁路径\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## RenderWare 对象 [#renderware-对象]\n\n<Api name=\"m_pRwObject / m_pRwClump / m_pRwAtomic\">\n  渲染钩子里判空。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      union {\n          struct RwObject* m_pRwObject;\n          struct RpClump* m_pRwClump;\n          struct RpAtomic* m_pRwAtomic;\n      };\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (!entity->m_pRwObject) {\n          return;\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n";
